sys_script_include.script:
var NeedItUtils = Class.create();
NeedItUtils.prototype = {
    initialize: function() {
    },
	isDatePast: function(strDate){
		// Create GlideDateTime objects for the current date and the passed in date
		var rightnow = new GlideDateTime();
		var testdate = new GlideDateTime(strDate);

		// If the testdate is before rightnow, return true, else return false
		if (testdate.before(rightnow)) {
			return true;
		}
		else {
			return false;
		}
	},
     // 新增：判断日期是否为今天
    isDateToday: function(strDate) {
        var testDate = new GlideDateTime(strDate);
        var today = new GlideDateTime();

		// 使用安全的本地时间方法获取年、月、日
		var testYear = testDate.getYearLocalTime();
		var testMonth = testDate.getMonthLocalTime();
		var testDay = testDate.getDayOfMonthLocalTime();

		var todayYear = today.getYearLocalTime();
		var todayMonth = today.getMonthLocalTime();
		var todayDay = today.getDayOfMonthLocalTime();

		// 如果年、月、日都相同，则为同一天
		return (testYear == todayYear && 
				testMonth == todayMonth && 
				testDay == todayDay);
    },
    type: 'NeedItUtils'
};
